/** A door scenario's world as the page would read it, and what the service then did (#336).
 *
 *  `testdata/scenarios/` is shared ground (ADR 0021): every file there was generated by running the
 *  REAL backend on its world. A page that predicts what a write will do — which rules a holding
 *  takes, which holding a total entry writes — can be held to those files rather than to a fake
 *  service written beside the prediction, which would only agree with itself.
 */
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";

import type { Holding, Monitor } from "../api";

type Row = Record<string, unknown>;

interface Scenario {
  world: { tables: Record<string, Row[] | undefined> };
  request: { body: unknown };
  expect: { rows: Record<string, { added?: Row[]; removed?: Row[]; changed?: { key: Row; from: Row; to: Row }[] }> };
}

export function scenario(name: string): Scenario {
  // under jsdom, Vite serves this module from `/@fs/<absolute path>`, and a `new URL(…, import.meta.url)`
  // naming the file would be taken for an asset import and refused: the path is built by hand
  const here = dirname(decodeURIComponent(new URL(import.meta.url).pathname).replace(/^\/@fs/, ""));
  return JSON.parse(readFileSync(resolve(here, "../../../testdata/scenarios/http", `${name}.json`), "utf8")) as Scenario;
}

const json = (v: unknown) => (typeof v === "string" ? JSON.parse(v) as unknown : v);

/** `/monitors` and the held part of `/positions/values`, as the world's tables would serve them. */
export function bookOf(s: Scenario): { monitors: Monitor[]; holdings: Holding[] } {
  const t = s.world.tables;
  const positions = (t.positions ?? []).filter((p) => p.closed_on === null || p.closed_on === undefined);
  const links = t.monitor_positions ?? [];
  const monitors = (t.monitors ?? []).map((m) => ({
    ...m,
    legs: json(m.legs),
    enabled: m.enabled === 1,
    triggered: m.triggered === 1,
    positions: links.filter((l) => l.monitor_id === m.id).map((l) => {
      const p = (t.positions ?? []).find((q) => q.id === l.position_id)!;
      return { id: p.id as string, name: p.name as string };
    }),
  })) as unknown as Monitor[];
  const holdings = positions.map((p) => ({ ...p, legs: json(p.legs) })) as unknown as Holding[];
  return { monitors, holdings };
}
